import sys; sys.path.insert(0,"/tmp/brandbuild"); sys.path.insert(0,"/tmp/dk")
import pdfkit
from pdfkit import *
D2="file:///tmp/design_out/"
TP=D2+"03_Poster_Templates/PNG/"; GP=D2+"03_Poster_Templates/Guides/PNG/"; BAD="file:///tmp/dk/bad/"
def tp(n): return TP+n+".png"
class DK(Doc): pass
pdfkit.PDF_OUT='/tmp/design_out'
from tpl import ICONS
def ic(name,color='#2563FF',size=8):
    return '<svg viewBox="0 0 24 24" width="%dmm" height="%dmm" fill="none" stroke="%s" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round">%s</svg>'%(size,size,color,ICONS[name])
P=Doc("Poster Playbook · Design Team",ver="v1.0")
def img(src,style="",cls="fit"): return '<img class="%s" src="%s" style="%s">'%(cls,src,style)
def pct(x,y,w,h,W=1080,H=1350): return "left:%.2f%%;top:%.2f%%;width:%.2f%%;height:%.2f%%"%(x/W*100,y/H*100,w/W*100,h/H*100)
def callout(box,n,label,side="r"):
    return '<div style="position:absolute;%s;border:2px solid #14D8C4;border-radius:6px"></div>'%box
# ---- 1 cover
P.page('<img src="%s" style="position:absolute;inset:0;width:100%%;height:100%%;object-fit:cover"><div style="position:absolute;left:18mm;top:18mm">%s</div><div style="position:absolute;left:18mm;bottom:28mm;right:90mm"><div class="eyebrow">Design Team · Poster Playbook · v1.0</div><h1 style="font-size:46pt;margin-top:4mm;line-height:1.02">Thiết kế poster<br><span style="color:#14D8C4">đúng Vibe AI Labs.</span></h1><p class="lead" style="margin-top:6mm">Quy tắc, layout, kích thước và checklist để làm poster nhanh, nhất quán và đúng thương hiệu.</p></div>'%(K+"/04_Graphic_Elements/PNG/ribbon-background_dark_16x9.png",logoimg("horizontal_reversed",h=11)),dark=True,header=False,footer=False)
# ---- 2 how to use
steps=[("01","Đọc brief","Một thông điệp, một CTA, kênh, tỉ lệ. Dùng `08_Export_Handoff/poster-brief-template.md`."),("02","Chọn layout (recipe)","6 layout R1–R6 trong `03_Poster_Templates`. Chọn theo mục tiêu (bảng ở trang 9)."),("03","Chọn tỉ lệ & tông","1:1 · 4:5 · 9:16 · 16:9 (và A3 in). Dark = tuyên bố/thương hiệu; Light = nội dung/giáo dục."),("04","Thay nội dung","Mở SVG (cài font trước), thay chữ theo `07_Copy_Library`. Đừng thêm chữ — chỉ rút gọn."),("05","Kiểm tra","Bật lớp `Guides`, chạy checklist QA (trang 15). Xem thử ở cỡ điện thoại."),("06","Xuất & bàn giao","PNG 2× + file nguồn + preview + caption. Đặt tên theo quy ước.")]
P.page('<div class="pad"><div class="eyebrow">01 · Cách dùng bộ kit</div><h2 style="margin:2mm 0 4mm">Sáu bước từ brief đến poster</h2><div class="grid g3">%s</div><div class="card soft" style="margin-top:6mm"><h3>Bản đồ thư mục</h3><div class="grid g4 small" style="margin-top:2mm"><div><b>00_START_HERE</b><br>Playbook, cheat sheet</div><div><b>01_Logos</b><br>Logo SVG/PNG, avatar</div><div><b>02_Color_Fonts</b><br>Màu, font, thang chữ</div><div><b>03_Poster_Templates</b><br>6 layout × 4 tỉ lệ × 2 tông + A3 + Guides</div><div><b>04_Components</b><br>Nút, tag, thẻ, badge</div><div><b>05_Backgrounds</b><br>Ruy-băng, sóng, orb</div><div><b>06_Icons</b><br>26 icon + pillar tiles</div><div><b>07/08/09</b><br>Copy · Handoff · Reference</div></div></div></div>'%"".join('<div class="card"><div class="num" style="font-size:20pt">%s</div><h3>%s</h3><p class="small">%s</p></div>'%s_ for s_ in steps),"01 · Cách dùng")
# ---- 3 anatomy
ann=[("1","Logo","Trên-trái, rộng 1/3 khung, vùng an toàn quanh logo",(86,86,360,62)),("2","Headline","≤ 8 từ, 2–3 dòng; dòng cuối gradient (Blue → Aqua)",(86,330,760,250)),("3","Dòng phụ","≤ 15 từ, Inter Medium, màu phụ",(86,588,580,46)),("4","CTA","Một nút duy nhất, nền Electric Blue, ≥ 72 px cao",(86,676,570,88)),("5","Họa tiết","Ruy-băng phóng lớn ở đáy, tràn mép, không che chữ",(120,990,960,360))]
boxes="".join('<div style="position:absolute;%s;border:.5mm solid #14D8C4;border-radius:2mm"></div><div style="position:absolute;left:%.2f%%;top:%.2f%%;width:6mm;height:6mm;margin:-3mm 0 0 -3mm;border-radius:50%%;background:#14D8C4;color:#0B1026;font-weight:800;text-align:center;line-height:6mm;font-size:9pt">%s</div>'%(pct(*b),b[0]/10.8,b[1]/13.5,n) for n,_,_,b in ann)
P.page('<div class="pad"><div class="eyebrow">02 · Giải phẫu poster</div><h2 style="margin:2mm 0 4mm">Năm thành phần, một thứ tự đọc</h2><div style="display:grid;grid-template-columns:auto 1fr;gap:10mm;align-items:start"><div style="position:relative;width:88mm"><img src="%s" style="width:100%%;display:block;border-radius:3mm">%s</div><div>%s<div class="card soft" style="margin-top:4mm"><h3>Thứ tự đọc</h3><p class="small">Mắt đi: <b>Headline → Logo → Dòng phụ → CTA</b>. Mỗi poster chỉ có <b>một</b> điểm nhìn đầu tiên (headline) và <b>một</b> hành động (CTA). Nếu cần thêm thông tin, chuyển xuống caption.</p></div></div></div></div>'%(tp("R1_announcement_4x5_dark"),boxes,"".join('<div style="display:flex;gap:3mm;margin:2mm 0"><div style="flex:none;width:6mm;height:6mm;border-radius:50%%;background:#14D8C4;color:#0B1026;font-weight:800;text-align:center;line-height:6mm;font-size:9pt">%s</div><div><b>%s</b><div class="small">%s</div></div></div>'%(n,t,d) for n,t,d,_ in ann)),"02 · Giải phẫu")
# ---- 4 five rules
rules=[("Một thông điệp","Mỗi poster chỉ nói một điều. Muốn nói hai điều → làm hai poster."),("Một CTA","Một hành động duy nhất (nhắn tin / đặt lịch / đọc thêm). Không đặt nhiều nút."),("≤ 30 từ","Headline ≤ 8 từ, tổng ≤ 30 từ. Phần còn lại để ở caption."),("Logo cố định","Dùng file logo, đúng biến thể theo nền, đủ vùng an toàn. Đổi nền/bố cục, không đổi logo."),("Gradient là năng lượng","Chỉ ở dòng tiêu đề cuối, ruy-băng, nền. Không gradient cho chữ nhỏ, nút, đoạn văn.")]
P.page('<div class="pad"><div class="eyebrow">03 · Quy tắc vàng</div><h2 style="margin:2mm 0 4mm">Năm quy tắc không thương lượng</h2><div class="grid g5">%s</div><div class="grid g2" style="margin-top:6mm"><div class="card soft"><h3>Còn nữa</h3><ul class="b small" style="margin-top:2mm"><li>Thứ tự luôn là <b>Marketing → AI → Creative</b>.</li><li>Dùng đúng font: Plus Jakarta Sans (tiêu đề) · Inter (chữ phụ).</li><li>Không emoji, không dấu chấm than liên tiếp, không HOA cả câu.</li></ul></div><div class="card soft"><h3>Khi nghi ngờ</h3><ul class="b small" style="margin-top:2mm"><li>Bớt chữ, thêm khoảng trắng.</li><li>Chọn nền tối + một gradient.</li><li>Hỏi người duyệt thương hiệu (Henry Le) trước khi phá quy tắc.</li></ul></div></div></div>'%"".join('<div class="card"><div class="num" style="font-size:22pt">%d</div><h3 style="margin-top:2mm">%s</h3><p class="small">%s</p></div>'%(i+1,t,d) for i,(t,d) in enumerate(rules)),"03 · Quy tắc vàng")
# ---- 5 formats & safe zones
def th5(n,g,l,h=46):
    return '<div><div style="position:relative;display:inline-block"><img src="%s" style="height:%dmm;display:block;border-radius:3mm"><img src="%s" style="position:absolute;inset:0;width:100%%;height:100%%;border-radius:3mm"></div><p class="tiny" style="margin-top:1mm"><b>%s</b></p></div>'%(tp(n),h,GP+"guides_%s.png"%g,l)
P.page('<div class="pad"><div class="eyebrow">04 · Kích thước & vùng an toàn</div><h2 style="margin:2mm 0 3mm">Mỗi định dạng một vùng an toàn</h2><div style="display:flex;gap:6mm;align-items:flex-end">%s</div><table style="margin-top:4mm;font-size:8pt"><tr><th>Định dạng</th><th>Thiết kế</th><th>Lề an toàn</th><th>Lưu ý</th></tr><tr><td>1:1 (Facebook, LinkedIn)</td><td>1080×1080</td><td>86 px (8%%)</td><td>Logo trên-trái, nội dung trong khung lề</td></tr><tr><td>4:5 (Facebook, Instagram)</td><td>1080×1350</td><td>86 px</td><td>Chiếm nhiều chỗ nhất trên feed</td></tr><tr><td>9:16 (Story, Reels)</td><td>1080×1920</td><td>86 px · trên 250 · dưới 340</td><td>Không đặt chữ trong vùng giao diện</td></tr><tr><td>16:9 (X, YouTube thumbnail)</td><td>1280×720</td><td>70 px</td><td>Chữ ở 56%% chiều rộng bên trái; họa tiết bên phải</td></tr><tr><td>A3 in</td><td>297×420 mm</td><td>≥ 10 mm</td><td>Thêm bleed 3 mm; xuất PDF</td></tr></table></div>'%"".join(th5(n,g,l) for n,g,l in (("R1_announcement_1x1_dark","1x1","1:1"),("R1_announcement_4x5_dark","4x5","4:5"),("R1_announcement_9x16_dark","9x16","9:16"),("R1_announcement_16x9_dark","16x9","16:9"))),"04 · Kích thước")
# ---- 6 typography
P.page('<div class="pad"><div class="eyebrow">05 · Chữ trên poster</div><h2 style="margin:2mm 0 3mm">Phân cấp chữ theo chiều rộng khung</h2><table><tr><th>Cấp</th><th>Font</th><th>Cỡ (khung 1080)</th><th>% chiều rộng</th><th>Ghi chú</th></tr><tr><td><b>Headline</b></td><td>Plus Jakarta Sans 800</td><td>110–125 px</td><td>10–11,5%%</td><td>Tracking −2,5%%; dòng cuối gradient</td></tr><tr><td><b>Eyebrow / nhãn</b></td><td>Plus Jakarta Sans 700</td><td>22–26 px</td><td>2–2,4%%</td><td>IN HOA, giãn chữ +0,2em, màu Aqua/Blue</td></tr><tr><td><b>Dòng phụ</b></td><td>Inter 500</td><td>28–32 px</td><td>2,6–3%%</td><td>Màu phụ #D9E2F2 (tối) / #667085 (sáng)</td></tr><tr><td><b>Nhãn thẻ</b></td><td>Plus Jakarta Sans 800</td><td>30–40 px</td><td>2,8–3,7%%</td><td>≤ 3 từ</td></tr><tr><td><b>Mô tả thẻ</b></td><td>Inter 500</td><td>22–25 px</td><td>2–2,3%%</td><td>≤ 5 từ; tối thiểu 18 px</td></tr><tr><td><b>CTA</b></td><td>Inter 600</td><td>28–36 px</td><td>2,6–3,3%%</td><td>Nút pill, cao ≥ 72 px, padding ngang 1,15 × cỡ chữ</td></tr><tr><td><b>Nguồn / chú thích</b></td><td>Inter 500</td><td>18–20 px</td><td>≥ 1,7%%</td><td>Chân poster, màu phụ</td></tr></table><div class="grid g3" style="margin-top:5mm"><div class="card soft"><h3>Nên</h3><ul class="b ok small" style="margin-top:2mm"><li>Căn trái; ngắt dòng theo nghĩa.</li><li>Dòng cách dòng headline 1,04–1,08.</li><li>Tối đa 3 cỡ chữ khác nhau.</li></ul></div><div class="card soft"><h3>Không</h3><ul class="b x small" style="margin-top:2mm"><li>Căn giữa đoạn dài; chữ nghiêng.</li><li>Trộn nhiều font; chữ có viền/bóng.</li><li>Chữ &lt; 18 px (khung 1080).</li></ul></div><div class="card soft"><h3>Tiếng Việt</h3><ul class="b small" style="margin-top:2mm"><li>Dấu cần chỗ: tăng line-height ≥ 1,04.</li><li>Kiểm tra dấu bị cắt ở dòng đầu (ê, ộ, ữ).</li></ul></div></div></div>',"05 · Chữ")
# ---- 7 colour
P.page('<div class="pad"><div class="eyebrow">06 · Màu trên poster</div><h2 style="margin:2mm 0 3mm">Dark hay Light?</h2><div class="grid g2"><div><img class="fit" src="%s"><div class="card soft" style="margin-top:3mm"><h3>Dark — nền Midnight</h3><p class="small">Tuyên bố thương hiệu, thông báo, sự kiện, số liệu nổi bật. Chữ trắng; nhấn Aqua / gradient Blue→Aqua.</p></div></div><div><img class="fit" src="%s" style="border:1px solid var(--line)"><div class="card soft" style="margin-top:3mm"><h3>Light — nền Cloud/White</h3><p class="small">Nội dung giáo dục, insight, danh sách. Chữ Midnight; nhấn Electric Blue. Aqua không làm chữ trên nền sáng.</p></div></div></div><div class="grid g2" style="margin-top:4mm"><div class="card"><h3>Tỉ lệ 60 · 30 · 10</h3><div style="display:flex;height:11mm;border-radius:3mm;overflow:hidden;margin-top:2mm"><div style="flex:60;background:#0B1026"></div><div style="flex:30;background:#2563FF"></div><div style="flex:10;background:#14D8C4"></div></div><p class="tiny" style="margin-top:1mm">Nền Midnight/Cloud · chữ & nút Electric Blue/trắng · nhấn Aqua/Violet/màu trụ</p></div><div class="card"><h3>Màu trụ dịch vụ</h3><div style="display:flex;gap:6mm;margin-top:3mm" class="small"><span class="chip"><span class="dot" style="background:#2563FF"></span>Marketing số</span><span class="chip"><span class="dot" style="background:#16A34A"></span>AI &amp; Tự động hóa</span><span class="chip"><span class="dot" style="background:#F97316"></span>Thiết kế &amp; Sáng tạo</span></div><p class="tiny" style="margin-top:1mm">Chỉ dùng cho icon, tag, đường nhấn của từng trụ — không đổi logo/nền.</p></div></div></div>'%(tp("R3_pillars_16x9_dark"),tp("R3_pillars_16x9_light")),"06 · Màu")
# ---- 8 recipes (6)
rec=[("R1","Announcement","Tuyên bố thương hiệu, thông báo, giới thiệu dịch vụ","R1_announcement"),("R2","Insight list","Bài giáo dục dạng “N cách / N bước / N câu hỏi”","R2_insight-list"),("R3","Pillars","Giải thích hệ thống / ba năng lực / quy trình 3 bước","R3_pillars"),("R4","Stat","Kết quả, số liệu nổi bật (có nguồn xác minh)","R4_stat"),("R5","Quote","Nhận xét khách hàng, trích dẫn chuyên gia","R5_quote"),("R6","Event","Webinar, workshop, ra mắt, ưu đãi có thời hạn","R6_event")]
P.page('<div class="pad"><div class="eyebrow">07 · Sáu layout (recipe)</div><h2 style="margin:2mm 0 3mm">Chọn layout theo mục tiêu</h2><div class="grid g6" style="gap:3mm">%s</div><table style="margin-top:5mm"><tr><th style="width:14mm">Mã</th><th style="width:34mm">Layout</th><th>Dùng khi</th><th style="width:60mm">Tên file</th></tr>%s</table><p class="small" style="margin-top:3mm">Mỗi layout có 4 tỉ lệ (1x1 · 4x5 · 9x16 · 16x9) × 2 tông (dark · light); R1, R3, R6 còn có bản A3 in. Nội dung mẫu là chỗ giữ chỗ — thay bằng nội dung thật.</p></div>'%("".join('<div><img class="fit" src="%s"><p class="tiny" style="margin-top:1mm"><b>%s · %s</b></p></div>'%(tp(f+"_1x1_dark"),a,b) for a,b,c,f in rec),"".join('<tr><td><b>%s</b></td><td>%s</td><td>%s</td><td class="tiny">%s_[tỉ-lệ]_[tông]</td></tr>'%(a,b,c,f) for a,b,c,f in rec)),"07 · Layout")
# ---- 9 ratios adaptation
P.page('<div class="pad"><div class="eyebrow">08 · Một layout, bốn tỉ lệ</div><h2 style="margin:2mm 0 3mm">Cùng nội dung — thích nghi theo khung</h2><div style="display:flex;gap:5mm;align-items:flex-end">%s</div><div class="grid g3" style="margin-top:4mm"><div class="card soft"><h3>1:1 · 4:5</h3><p class="small">Xếp dọc: logo → headline → phụ → CTA; họa tiết ở đáy.</p></div><div class="card soft"><h3>9:16</h3><p class="small">Nội dung nằm giữa vùng an toàn (250 px trên, 340 px dưới); họa tiết lớn hơn ở đáy.</p></div><div class="card soft"><h3>16:9</h3><p class="small">Chữ ở 56%% bên trái, họa tiết hoặc thẻ ở bên phải; headline cao hơn ~10%%.</p></div></div></div>'%"".join('<div><img src="%s" style="height:46mm;display:block;border-radius:3mm"><p class="tiny" style="margin-top:1mm"><b>%s</b></p></div>'%(tp("R2_insight-list_%s_dark"%r),r.replace("x",":")) for r in ("1x1","4x5","9x16","16x9")),"08 · Tỉ lệ")
# ---- 10 logo on poster
P.page('<div class="pad"><div class="eyebrow">09 · Logo trên poster</div><h2 style="margin:2mm 0 3mm">Đặt logo đúng chỗ, đúng biến thể</h2><div class="grid g4">%s</div><table style="margin-top:5mm"><tr><th>Khung</th><th>Vị trí</th><th>Chiều rộng logo</th></tr><tr><td>1:1 · 4:5 (1080)</td><td>Trên-trái, cách mép 86 px</td><td>360 px (1/3)</td></tr><tr><td>9:16</td><td>Trên-trái, y = 270 px (dưới vùng giao diện)</td><td>380 px</td></tr><tr><td>16:9 (1280)</td><td>Trên-trái, cách mép 70 px</td><td>300 px</td></tr><tr><td>Avatar / nhỏ</td><td>Chỉ dùng icon ruy-băng</td><td>≥ 24 px</td></tr></table><div class="grid g2" style="margin-top:4mm"><div class="card soft"><ul class="b ok small"><li>Nền tối → logo <b>Reversed</b>; nền sáng → <b>Color</b>; nền màu bão hòa → <b>White</b>.</li><li>Vùng an toàn = 1 × đường kính chấm tròn.</li></ul></div><div class="card soft"><ul class="b x small"><li>Không kéo giãn, đổi màu, thêm bóng/viền, xoay.</li><li>Không đặt logo bản màu lên ảnh/nền rối.</li></ul></div></div></div>'%"".join('<div><div class="stage" style="height:28mm;background:%s;border-color:#D9E2F2"><img src="%s" style="max-width:80%%;max-height:70%%"></div><p class="small" style="margin-top:1mm"><b>%s</b></p></div>'%(bg,L(n),l) for bg,n,l in (("#FFFFFF","horizontal_color_1000px","Color · nền sáng"),("#0B1026","horizontal_reversed_1000px","Reversed · nền tối"),("#2563FF","horizontal_white_1000px","White · nền màu"),("#F8FAFC","icon_color_1024px","Icon · avatar"))),"09 · Logo")
# ---- 11 imagery
P.page('<div class="pad"><div class="eyebrow">10 · Nền, hình ảnh, icon</div><h2 style="margin:2mm 0 3mm">Họa tiết thương hiệu trước, ảnh sau</h2><div class="grid g4"><div><img class="fit" src="%s"><p class="tiny"><b>Ruy-băng</b> — nền chính (05_Backgrounds)</p></div><div><img class="fit" src="%s"><p class="tiny"><b>Sóng đường mảnh</b> — nền phụ</p></div><div style="background:#0B1026;border-radius:3mm;padding:4mm;text-align:center"><img src="%s" style="width:60%%"><p class="tiny" style="color:#9FB0D6"><b>Orb</b> — điểm nhấn</p></div><div class="card" style="text-align:center">%s<p class="tiny"><b>Icon</b> 26 biểu tượng, nét 1,75 px</p></div></div><div class="grid g2" style="margin-top:5mm"><div class="card soft"><h3>Ảnh chụp</h3><ul class="b ok small" style="margin-top:2mm"><li>Bối cảnh kinh doanh thật, cụ thể, đáng tin; ánh sáng tự nhiên.</li><li>Chừa vùng thoáng cho chữ; chỉnh màu nhất quán trong một chiến dịch.</li><li>Phủ lớp Midnight 40–60%% nếu cần tăng tương phản cho chữ trắng.</li></ul></div><div class="card soft"><h3>Ảnh AI tạo sinh</h3><ul class="b small" style="margin-top:2mm"><li>Viết brief hình ảnh (mục tiêu, màu thương hiệu, ánh sáng, bố cục).</li><li>Duyệt giải phẫu, chữ, logo, chi tiết sản phẩm; không mô phỏng người thật khi chưa được phép.</li><li>Tránh robot, bộ não phát sáng, ma trận xanh lá.</li></ul></div></div></div>'%(K+"/04_Graphic_Elements/PNG/ribbon-background_dark_16x9.png",K+"/04_Graphic_Elements/PNG/wave-lines_dark_16x9.png",K+"/04_Graphic_Elements/PNG/gradient-orb.png",'<div style="display:flex;gap:3mm;justify-content:center;flex-wrap:wrap">'+"".join(ic(n_,"#2563FF",9) for n_ in ("growth","ai","design","strategy","automation","chatbot"))+'</div>'),"10 · Hình ảnh")
# ---- 12 copy
P.page('<div class="pad"><div class="eyebrow">11 · Viết chữ cho poster</div><h2 style="margin:2mm 0 3mm">Ít chữ hơn bạn nghĩ</h2><div class="grid g2"><div class="card"><h3>Giới hạn</h3><table style="margin-top:2mm"><tr><td>Headline</td><td><b>≤ 8 từ</b>, ≤ 3 dòng</td></tr><tr><td>Dòng phụ</td><td>≤ 15 từ</td></tr><tr><td>Nhãn thẻ / mô tả</td><td>≤ 3 / ≤ 5 từ</td></tr><tr><td>CTA</td><td>2–4 từ, động từ, <b>một</b></td></tr><tr><td>Tổng</td><td><b>≤ 30 từ</b> (≤ 40 với danh sách/sự kiện)</td></tr></table></div><div class="card"><h3>Công thức headline</h3><ul class="b small" style="margin-top:2mm"><li><b>Hai vế:</b> “Ba năng lực. Một hệ thống.”</li><li><b>Số + lợi ích:</b> “5 cách AI giúp thương hiệu tăng trưởng nhanh hơn”</li><li><b>Câu hỏi:</b> “Chưa biết bắt đầu AI từ đâu?”</li><li><b>Từ A đến B:</b> “Từ ý tưởng đến tăng trưởng thực.”</li></ul></div></div><div class="card soft" style="margin-top:5mm"><h3>Trước → Sau</h3><table style="margin-top:2mm"><tr><td class="small"><span class="badge-x">Trước</span> Marketing × AI × Creative: Giải pháp tích hợp cho bài toán tăng trưởng và vận hành</td><td class="small"><span class="badge-ok">Sau</span> <b>Ba năng lực. Một hệ thống.</b></td></tr><tr><td class="small"><span class="badge-x">Trước</span> Doanh nghiệp của bạn đang gặp khó khăn trong Marketing, vận hành hay ứng dụng AI? Hãy nhắn tin…</td><td class="small"><span class="badge-ok">Sau</span> <b>Nhắn tin cho chúng tôi →</b></td></tr></table></div><p class="small" style="margin-top:3mm">Nguyên tắc: thứ gì không giúp người xem dừng lại, hiểu hoặc hành động → chuyển xuống caption. Thư viện đầy đủ: <b>07_Copy_Library</b>.</p></div>',"11 · Viết chữ")
# ---- 13 good vs bad
P.page('<div class="pad"><div class="eyebrow">12 · Sai và đúng</div><h2 style="margin:2mm 0 3mm">Ba lỗi hay gặp</h2><div class="grid g4"><div><img class="fit" src="%s" style="border:2px solid #E11D48"><p class="small" style="margin-top:2mm"><span class="badge-x">Sai · quá nhiều chữ</span><br>Đoạn dài, 3 CTA, emoji, nhiều dấu chấm than, chữ nhỏ 22 px.</p></div><div><img class="fit" src="%s" style="border:2px solid #E11D48"><p class="small" style="margin-top:2mm"><span class="badge-x">Sai · màu & tương phản</span><br>Aqua làm chữ trên nền sáng, hai gradient, chữ nút trùng màu nền nút.</p></div><div><img class="fit" src="%s" style="border:2px solid #E11D48"><p class="small" style="margin-top:2mm"><span class="badge-x">Sai · logo & phân cấp</span><br>Logo méo + bóng, trộn font/màu, không có lưới.</p></div><div><img class="fit" src="%s" style="border:2px solid #16A34A"><p class="small" style="margin-top:2mm"><span class="badge-ok">Đúng</span><br>Một thông điệp, một CTA, phân cấp rõ, logo chuẩn, tương phản đạt AA.</p></div></div></div>'%(BAD+"bad_1.png",BAD+"bad_2.png",BAD+"bad_3.png",tp("R1_announcement_1x1_dark")),"12 · Sai và đúng")
# ---- 14 QA + export
P.page('<div class="pad"><div class="eyebrow">13 · Kiểm tra & xuất file</div><h2 style="margin:2mm 0 3mm">Trước khi gửi duyệt</h2><div class="grid g2"><div class="card"><h3>Checklist</h3><ul class="b small" style="margin-top:2mm"><li>☐ Một thông điệp, một CTA; ≤ 30 từ; không emoji.</li><li>☐ Đúng chính tả & dấu; đúng “Vibe AI Labs”; đúng thứ tự Marketing → AI → Creative.</li><li>☐ Số liệu có nguồn + kỳ đo (hoặc chưa đăng).</li><li>☐ Logo đúng biến thể, không méo, đủ vùng an toàn.</li><li>☐ Font Plus Jakarta Sans + Inter; màu đúng bảng; ≤ 1 gradient.</li><li>☐ Lề ≥ 8%; story chừa 250/340 px.</li><li>☐ Chữ ≥ 28 px (thân), ≥ 18 px (nhỏ nhất); đạt AA.</li><li>☐ Thử thu nhỏ ~360 px: đọc được headline + CTA.</li></ul></div><div class="card"><h3>Xuất & đặt tên</h3><ul class="b small" style="margin-top:2mm"><li>PNG sRGB, xuất 2× (vd. 2160×2160); ≤ 5 MB; JPG 90 nếu có ảnh chụp.</li><li>In A3: PDF, bleed 3 mm, font nhúng, theo profile nhà in.</li><li><code>vibe-ai-labs_[kênh]_[chủ-đề]_[tỉ-lệ]_[tông]_v01.png</code></li><li>Gửi kèm: file nguồn + preview + caption + ghi chú nguồn ảnh/số liệu.</li></ul></div></div></div>',"13 · Kiểm tra")
# ---- 15 workflow & contact
P.page('<div class="pad"><div class="eyebrow">14 · Quy trình duyệt & liên hệ</div><h2 style="margin:2mm 0 3mm">Ai duyệt, duyệt khi nào</h2><div style="display:flex;gap:3mm;align-items:stretch">%s</div><div class="grid g2" style="margin-top:6mm"><div class="card soft"><h3>Phê duyệt</h3><ul class="b small" style="margin-top:2mm"><li>Người duyệt cuối: <b>Henry Le</b> — Marketing Engineer · Founder.</li><li>Mọi ngoại lệ so với playbook phải được duyệt bằng văn bản trước khi đăng.</li><li>Thay đổi kit (logo, màu, font) chỉ do người phụ trách thương hiệu cập nhật.</li></ul></div><div class="card d" style="padding:6mm"><div class="eyebrow" style="color:#14D8C4">Liên hệ</div><div class="kv" style="margin-top:2mm;color:#E8EEFF"><b style="color:#fff">Email</b><span>vibeailabs@gmail.com</span><b style="color:#fff">Website</b><span>vibe-ai-labs.vibeailabs.workers.dev</span><b style="color:#fff">Địa chỉ</b><span>WORC@Q2 Building, 21 Võ Trường Toản, An Khánh, TP.HCM</span></div></div></div></div>'%"".join('<div class="card" style="flex:1;text-align:center"><div class="num" style="font-size:16pt">%d</div><h3>%s</h3><p class="tiny">%s</p></div>'%(i+1,t,d) for i,(t,d) in enumerate((("Brief","Điền brief 1 trang"),("Bản nháp","Layout + chữ rút gọn"),("Tự kiểm","Checklist QA"),("Duyệt","Người duyệt thương hiệu"),("Xuất","PNG 2× + nguồn"),("Đăng","Kèm caption")))),"14 · Quy trình")
